/* C API of the Rust port of `weather.c`, generated by rust-anything. */
#ifndef WEATHER_RS_H
#define WEATHER_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

double calculateWaterBoundaryConvectionCoefficient(double curWaterTemp, double curWaterVelocity, double distanceFromLeadingEdge);
double interpolateWindDirection(double prevHrWindDir, double curHrWindDir, double curHrWeight);
double AirMass(double CosZen);
double GetSTM(double Longitude);
bool isLeapYear(int Year);
int computeJulianDate(int gyyyy, int gmm, int gdd);
int calculateDayOfYear(int Month, int Day, bool leapYear);
bool validMonthDay(int month, int day, int leapYearAdd);

/* The same functions under `rust_anything_` names, for shadow runs. */
double rust_anything_calculateWaterBoundaryConvectionCoefficient(double curWaterTemp, double curWaterVelocity, double distanceFromLeadingEdge);
double rust_anything_interpolateWindDirection(double prevHrWindDir, double curHrWindDir, double curHrWeight);
double rust_anything_AirMass(double CosZen);
double rust_anything_GetSTM(double Longitude);
bool rust_anything_isLeapYear(int Year);
int rust_anything_computeJulianDate(int gyyyy, int gmm, int gdd);
int rust_anything_calculateDayOfYear(int Month, int Day, bool leapYear);
bool rust_anything_validMonthDay(int month, int day, int leapYearAdd);

#endif /* WEATHER_RS_H */
